:root {
  --bg: #0b1220;
  --bg-elevated: #111a2e;
  --bg-card: #152238;
  --bg-card-hover: #1a2944;
  --border: rgba(148, 163, 184, 0.16);
  --border-strong: rgba(148, 163, 184, 0.28);
  --text: #e5eefc;
  --text-muted: #9fb0cc;
  --brand: #7c3aed;
  --brand-2: #22c55e;
  --brand-soft: rgba(124, 58, 237, 0.16);
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.28);
  --ring: 0 0 0 3px rgba(124, 58, 237, 0.35);
}

html, body {
  min-height: 100%;
}

body {
  margin: 0;
  color: var(--text);
  background:
    radial-gradient(circle at top, rgba(124, 58, 237, 0.16), transparent 34%),
    radial-gradient(circle at 20% 20%, rgba(34, 197, 94, 0.08), transparent 28%),
    linear-gradient(180deg, #0b1220 0%, #0a1020 100%);
}

* {
  box-sizing: border-box;
}

a {
  color: inherit;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  transition: transform 160ms ease, background-color 160ms ease, border-color 160ms ease, box-shadow 160ms ease, opacity 160ms ease;
}

button:hover {
  transform: translateY(-1px);
}

button:active {
  transform: translateY(0);
}

.card,
.panel,
.shadow-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  transition: background-color 160ms ease, border-color 160ms ease, transform 160ms ease, box-shadow 160ms ease;
}

.card:hover,
.panel:hover,
.shadow-card:hover {
  background: var(--bg-card-hover);
  border-color: var(--border-strong);
}

input,
textarea,
select {
  background-color: #0f172a;
  color: var(--text);
  border: 1px solid var(--border-strong);
  border-radius: 0.75rem;
  transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
}

input::placeholder,
textarea::placeholder {
  color: #7f8ea8;
}

input:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: rgba(124, 58, 237, 0.75);
  box-shadow: var(--ring);
}

input[type="checkbox"],
input[type="radio"] {
  accent-color: var(--brand);
}

.view-enter {
  animation: fade-in 220ms ease-out both;
}

@keyframes fade-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

table {
  width: 100%;
  border-collapse: collapse;
  color: var(--text);
  background: transparent;
}

th,
td {
  padding: 0.75rem 0.875rem;
  border-bottom: 1px solid var(--border);
  text-align: left;
  vertical-align: middle;
}

th {
  font-size: 0.75rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
  background: rgba(255, 255, 255, 0.02);
}

tbody tr {
  transition: background-color 160ms ease;
}

tbody tr:hover {
  background: rgba(124, 58, 237, 0.08);
}

#login-view,
#app-view {
  width: 100%;
  max-width: 100%;
}

.container,
.wrapper,
main {
  width: 100%;
  max-width: 100%;
}

@media (max-width: 420px) {
  body {
    background-attachment: scroll;
  }

  th,
  td {
    padding: 0.65rem 0.7rem;
  }

  .card,
  .panel,
  .shadow-card {
    border-radius: 1rem;
  }
}

(() => {
  const AUTH_KEY = 'app:auth';
  const ENTITIES_KEY = 'app:entities';

  const demoCreds = { email: 'demo@example.com', password: 'demo' };

  const qs = (sel) => document.querySelector(sel);
  const qsa = (sel) => Array.from(document.querySelectorAll(sel));

  const readJSON = (key, fallback) => {
    try {
      const raw = localStorage.getItem(key);
      if (!raw) return fallback;
      return JSON.parse(raw);
    } catch {
      return fallback;
    }
  };

  const writeJSON = (key, value) => localStorage.setItem(key, JSON.stringify(value));

  const api = {
    list() {
      return readJSON(ENTITIES_KEY, []);
    },
    create(obj) {
      const current = api.list();
      const entity = {
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString(),
        ...obj
      };
      current.push(entity);
      writeJSON(ENTITIES_KEY, current);
      return entity;
    },
    remove(id) {
      const filtered = api.list().filter((item) => item.id !== id);
      writeJSON(ENTITIES_KEY, filtered);
    }
  };

  function seedEntitiesIfEmpty() {
    const existing = api.list();
    if (existing.length) return;
    const seeds = [
      {
        location: 'Downtown Salon',
        service: 'Haircut',
        customer: 'Ava Johnson',
        amount: 45,
        status: 'confirmed',
        slot: '2026-07-08T10:00:00.000Z'
      },
      {
        location: 'North Clinic',
        service: 'Consultation',
        customer: 'Marcus Lee',
        amount: 120,
        status: 'deposit_paid',
        slot: '2026-07-08T11:30:00.000Z'
      },
      {
        location: 'West Fitness Studio',
        service: 'Personal Training',
        customer: 'Priya Patel',
        amount: 65,
        status: 'pending',
        slot: '2026-07-08T14:00:00.000Z'
      },
      {
        location: 'East Repair Shop',
        service: 'Phone Repair',
        customer: 'Sam Rivera',
        amount: 89,
        status: 'confirmed',
        slot: '2026-07-08T15:30:00.000Z'
      }
    ];
    writeJSON(ENTITIES_KEY, seeds.map((s) => ({ id: crypto.randomUUID(), createdAt: new Date().toISOString(), ...s })));
  }

  function showApp(isLoggedIn) {
    const loginView = qs('#login-view');
    const appView = qs('#app-view');
    if (loginView) loginView.style.display = isLoggedIn ? 'none' : '';
    if (appView) appView.style.display = isLoggedIn ? '' : 'none';
  }

  function setLoginError(message) {
    const el = qs('#login-error');
    if (!el) return;
    el.textContent = message || '';
  }

  function formatMoney(amount) {
    const n = Number(amount || 0);
    return n.toLocaleString(undefined, { style: 'currency', currency: 'USD' });
  }

  function formatDate(value) {
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return '—';
    return d.toLocaleString();
  }

  function renderKpis() {
    const entities = api.list();
    const total = entities.length;
    const revenue = entities.reduce((sum, item) => sum + Number(item.amount || 0), 0);
    const confirmed = entities.filter((item) => item.status === 'confirmed').length;
    const pending = entities.filter((item) => item.status === 'pending').length;
    const bookedToday = entities.filter((item) => {
      const d = new Date(item.slot || item.createdAt);
      const now = new Date();
      return d.toDateString() === now.toDateString();
    }).length;

    const strip = qs('#kpi-strip');
    if (!strip) return;

    strip.innerHTML = `
      <div class="kpi"><strong>${total}</strong><span>Bookings</span></div>
      <div class="kpi"><strong>${formatMoney(revenue)}</strong><span>Gross sales</span></div>
      <div class="kpi"><strong>${confirmed}</strong><span>Confirmed</span></div>
      <div class="kpi"><strong>${pending}</strong><span>Pending</span></div>
      <div class="kpi"><strong>${bookedToday}</strong><span>Today</span></div>
    `;
  }

  function renderList() {
    const list = api.list();
    const container = qs('#entity-list');
    if (!container) return;

    if (!list.length) {
      container.innerHTML = '<p>No bookings yet.</p>';
      return;
    }

    const rows = list
      .map(
        (item) => `
        <tr>
          <td>${escapeHtml(item.location || '')}</td>
          <td>${escapeHtml(item.service || '')}</td>
          <td>${escapeHtml(item.customer || '')}</td>
          <td>${formatDate(item.slot || item.createdAt)}</td>
          <td>${formatMoney(item.amount)}</td>
          <td>${escapeHtml(item.status || '')}</td>
          <td><button type="button" class="delete-btn" data-id="${item.id}">Delete</button></td>
        </tr>`
      )
      .join('');

    container.innerHTML = `
      <table>
        <thead>
          <tr>
            <th>Location</th>
            <th>Service</th>
            <th>Customer</th>
            <th>Slot</th>
            <th>Amount</th>
            <th>Status</th>
            <th></th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    `;
  }

  function escapeHtml(value) {
    return String(value)
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#39;');
  }

  function renderAll() {
    renderList();
    renderKpis();
  }

  function bindAuth() {
    const loginBtn = qs('#login-btn');
    const emailInput = qs('#login-email');
    const passInput = qs('#login-password');

    if (!loginBtn) return;

    loginBtn.addEventListener('click', () => {
      setLoginError('');
      const email = (emailInput && emailInput.value.trim()) || '';
      const password = (passInput && passInput.value) || '';

      if (email === demoCreds.email && password === demoCreds.password) {
        writeJSON(AUTH_KEY, { email, loggedAt: new Date().toISOString() });
        showApp(true);
        renderAll();
      } else {
        setLoginError('Invalid demo credentials. Try demo@example.com / demo');
      }
    });

    const form = loginBtn.closest('form');
    if (form) {
      form.addEventListener('submit', (e) => {
        e.preventDefault();
        loginBtn.click();
      });
    }
  }

  function bindLogout() {
    const logoutBtn = qs('#logout-btn');
    if (!logoutBtn) return;
    logoutBtn.addEventListener('click', () => {
      localStorage.removeItem(AUTH_KEY);
      location.reload();
    });
  }

  function bindCreateForm() {
    const form = qs('#create-form');
    if (!form) return;

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const fd = new FormData(form);

      const entity = {
        location: String(fd.get('location') || '').trim(),
        service: String(fd.get('service') || '').trim(),
        customer: String(fd.get('customer') || '').trim(),
        amount: Number(fd.get('amount') || 0),
        status: String(fd.get('status') || 'pending').trim(),
        slot: String(fd.get('slot') || new Date().toISOString())
      };

      if (!entity.location || !entity.service || !entity.customer) return;

      api.create(entity);
      form.reset();
      renderAll();
    });
  }

  function bindListActions() {
    const container = qs('#entity-list');
    if (!container) return;
    container.addEventListener('click', (e) => {
      const btn = e.target.closest('.delete-btn');
      if (!btn) return;
      const id = btn.getAttribute('data-id');
      if (!id) return;
      api.remove(id);
      renderAll();
    });
  }

  function init() {
    console.info('App ready · vanilla SPA · swap localStorage for backend/server.py to ship');
    seedEntitiesIfEmpty();

    const auth = readJSON(AUTH_KEY, null);
    showApp(Boolean(auth && auth.email));

    bindAuth();
    bindLogout();
    bindCreateForm();
    bindListActions();

    if (auth && auth.email) {
      renderAll();
    } else {
      setLoginError('');
    }
  }

  document.addEventListener('DOMContentLoaded', init);
})();

from __future__ import annotations

from datetime import datetime, timezone
from typing import Any, Dict, List, Optional
from uuid import uuid4

from fastapi import FastAPI, HTTPException, Request, status
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, ConfigDict, EmailStr, Field

APP_VERSION = "1.0.0"

app = FastAPI(title="BookNest API", version=APP_VERSION)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# In-memory demo storage. In production, this would be replaced by a real DB layer
# (e.g. PostgreSQL via SQLAlchemy/SQLModel, with proper persistence and indexing).
entities_by_id: Dict[str, Dict[str, Any]] = {}
sessions_by_token: Dict[str, Dict[str, Any]] = {}

demo_user = {
    "id": "demo-user",
    "email": "demo@example.com",
    "name": "Demo User",
    "role": "owner",
}


class LoginReq(BaseModel):
    email: str
    password: str


class User(BaseModel):
    model_config = ConfigDict(extra="ignore")

    id: str
    email: EmailStr
    name: str
    role: str


class LoginRes(BaseModel):
    token: str
    user: User


class EntityIn(BaseModel):
    title: str = Field(min_length=1)
    amount: float = 0


class EntityOut(EntityIn):
    id: str
    createdAt: str


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def auth_user(request: Request) -> Dict[str, Any]:
    auth = request.headers.get("Authorization", "")
    if not auth.startswith("Bearer "):
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Unauthorized")
    token = auth.removeprefix("Bearer ").strip()
    user = sessions_by_token.get(token)
    if not user:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Unauthorized")
    return user


@app.get("/api/health")
def health() -> Dict[str, str]:
    return {"status": "ok", "version": APP_VERSION}


@app.post("/api/auth/login", response_model=LoginRes)
def login(payload: LoginReq) -> LoginRes:
    if payload.email != "demo@example.com" or payload.password != "demo":
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid credentials")

    token = uuid4().hex
    sessions_by_token[token] = demo_user
    return LoginRes(token=token, user=User(**demo_user))


@app.get("/api/auth/me", response_model=User)
def me(request: Request) -> User:
    user = auth_user(request)
    return User(**user)


@app.get("/api/entities", response_model=List[EntityOut])
def list_entities(request: Request) -> List[EntityOut]:
    auth_user(request)
    return [EntityOut(**entity) for entity in entities_by_id.values()]


@app.post("/api/entities", response_model=EntityOut, status_code=status.HTTP_201_CREATED)
def create_entity(payload: EntityIn, request: Request) -> EntityOut:
    auth_user(request)
    entity_id = uuid4().hex
    entity = {
        "id": entity_id,
        "createdAt": now_iso(),
        "title": payload.title,
        "amount": payload.amount,
    }
    entities_by_id[entity_id] = entity
    return EntityOut(**entity)


@app.delete("/api/entities")
def delete_entity(request: Request, id: str) -> Dict[str, bool]:
    auth_user(request)
    if id not in entities_by_id:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Entity not found")
    del entities_by_id[id]
    return {"ok": True}
